output.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?spouse ?spouseLabel WHERE {
  dbr:Days_and_Hours(dbo:director | dbp:director) ?director .
  ?director(dbo:spouse | dbp:spouse | dbp:partner | dbo:partner) ?spouse .
  OPTIONAL {
    ?spouse rdfs:label ?spouseLabel .
    FILTER(lang(?spouseLabel) = "en")
  }
}

